      <div id="__formMsg" style="display:none;padding:.9rem 1rem;border-radius:10px;font-size:.9rem;margin-bottom:.9rem;"></div>
      <button type="submit" id="__submitBtn" style="width:100%;padding:1rem;background:linear-gradient(135deg,#d6b041,#f5df88);color:#17100a;font-weight:900;font-size:1rem;border:none;border-radius:999px;cursor:pointer;">送信する</button>
    </form>
    <script>
    (function () {
      var form = document.getElementById('__contactForm');
      if (!form) return;
      form.addEventListener('submit', async function(e) {
        e.preventDefault();
        var btn = document.getElementById('__submitBtn');
        var msg = document.getElementById('__formMsg');
        btn.disabled = true;
        btn.textContent = '送信中...';
        msg.style.display = 'none';
        var data = {};
        new FormData(form).forEach(function(v, k) { data[k] = v; });
        try {
          var res = await fetch('/contact.php', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(data)});
          var json = await res.json();
          msg.style.display = 'block';
          if (json.success) {
            msg.style.cssText = 'display:block;background:rgba(6,199,85,.12);border:1px solid rgba(6,199,85,.45);color:#70e69d;padding:.9rem 1rem;border-radius:10px;font-size:.9rem;margin-bottom:.9rem;';
            msg.textContent = json.message;
            form.reset();
          } else {
            msg.style.cssText = 'display:block;background:rgba(190,48,48,.18);border:1px solid rgba(190,48,48,.5);color:#ff9b9b;padding:.9rem 1rem;border-radius:10px;font-size:.9rem;margin-bottom:.9rem;';
            msg.textContent = (json.errors || []).join(' / ') || json.message || '送信に失敗しました。';
          }
        } catch (err) {
          msg.style.display = 'block';
          msg.style.cssText = 'display:block;background:rgba(190,48,48,.18);border:1px solid rgba(190,48,48,.5);color:#ff9b9b;padding:.9rem 1rem;border-radius:10px;font-size:.9rem;margin-bottom:.9rem;';
          msg.textContent = '通信エラーが発生しました。時間をおいて再度お試しください。';
        } finally {
          btn.disabled = false;
          btn.textContent = '送信する';
          msg.scrollIntoView({behavior:'smooth', block:'nearest'});
        }
      });
    })();
    </script>
    <?php endif; ?>
  </div>
</section>
<?php endif; ?>
<script>
(function () {
  function scrollToContact() {
    var target = document.getElementById('snk-agency-contact');
    if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
  function handleLineOrContact(event) {
    var lineUrl = <?= json_encode($showLinBtn ? '/line_click.php?agent_id=' . (int)$agent['id'] : '', JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?>;
    if (lineUrl) {
      window.open(lineUrl, '_blank', 'noopener');
      return;
    }
    event.preventDefault();
    scrollToContact();
  }
  ['snk-cta', 'snk-bottom-cta'].forEach(function (id) {
    var el = document.getElementById(id);
    if (el) el.addEventListener('click', handleLineOrContact);
  });
  Array.prototype.forEach.call(document.querySelectorAll('button, a'), function (el) {
    var text = (el.textContent || '').replace(/\s+/g, '');
    if (text.indexOf('LINE') !== -1 || text.indexOf('問い合わせ') !== -1) {
      el.addEventListener('click', handleLineOrContact);
    } else if (text.indexOf('フォーム') !== -1) {
      el.addEventListener('click', function (event) { event.preventDefault(); scrollToContact(); });
    }
  });
})();
</script>
</body>
</html>

